set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000003","session_id":"00000000-0000-0000-0000-000000000003"}',true);
select pg_temp.assert_true((select count(*)=1 from public.tutor_profiles), 'private tutor profile isolated');
select public.save_tutor_bio('  Stored biography  ',1);
select pg_temp.assert_true((select bio='Stored biography' and revision=2 from public.tutor_profiles), 'bio persists and revision increments');
select public.save_tutor_bio('Stored biography',1);
select pg_temp.assert_true((select revision=2 from public.tutor_profiles), 'duplicate biography request idempotent');
select pg_temp.expect_error($q$select public.save_tutor_bio('stale',1)$q$,'40001','stale biography rejected');
select pg_temp.expect_error($q$select public.save_tutor_bio(repeat('a',1201),2)$q$,'22023','long biography rejected');
select pg_temp.expect_error($q$select public.save_tutor_bio(null,2)$q$,'22023','null biography rejected');
select pg_temp.expect_error($q$update public.tutor_profiles set bio='bypass'$q$,'42501','direct bio bypass revoked');
select pg_temp.expect_error($q$update public.tutor_profiles set completed_sessions=20$q$,'42501','session-count forgery rejected');
select pg_temp.expect_error($q$update public.tutor_profiles set revision=1$q$,'42501','revision forgery rejected');
select pg_temp.expect_error($q$update public.tutor_profiles set academic_grade=12$q$,'42501','grade forgery rejected');
select pg_temp.expect_error($q$update public.tutor_profiles set teaching_skill_score=99$q$,'42501','score forgery rejected');
select pg_temp.expect_error($q$delete from public.tutor_verification_records$q$,'42501','immutable verification');
select pg_temp.expect_error($q$update public.tutor_subject_qualifications set subject_id='cbse-10-mathematics'$q$,'42501','subject tampering rejected');
select pg_temp.expect_error($q$delete from public.tutor_languages$q$,'42501','language tampering rejected');
select public.save_tutor_availability('80000000-0000-0000-0000-000000000001',null,1::smallint,'17:00'::time,'18:00'::time,true);
select public.save_tutor_availability('80000000-0000-0000-0000-000000000001',null,1::smallint,'17:00'::time,'18:00'::time,true);
select pg_temp.assert_true((select count(*)=2 from public.tutor_availability), 'adjacency allowed and duplicate request idempotent');
select pg_temp.expect_error($q$select public.save_tutor_availability('80000000-0000-0000-0000-000000000002',null,1::smallint,'16:30'::time,'17:30'::time,false)$q$,'23P01','disabled overlap rejected');
select pg_temp.expect_error($q$select public.save_tutor_availability('80000000-0000-0000-0000-000000000002',null,1::smallint,'17:00'::time,'18:00'::time,true)$q$,'23505','duplicate interval rejected');
select pg_temp.expect_error($q$select public.save_tutor_availability('80000000-0000-0000-0000-000000000002',null,1::smallint,'20:00'::time,'19:00'::time,true)$q$,'23514','inverted interval rejected');
select pg_temp.expect_error($q$select public.save_tutor_availability('80000000-0000-0000-0000-000000000002',null,1::smallint,'19:00'::time,'19:10'::time,true)$q$,'23514','too-short interval rejected');
select pg_temp.expect_error($q$select public.save_tutor_availability('80000000-0000-0000-0000-000000000002',null,1::smallint,'19:00'::time,'23:01'::time,true)$q$,'23514','too-long interval rejected');
select pg_temp.expect_error($q$select public.save_tutor_availability('80000000-0000-0000-0000-000000000002',null,1::smallint,'19:00:01'::time,'20:00'::time,true)$q$,'23514','non-minute precision rejected');
select public.save_tutor_availability('80000000-0000-0000-0000-000000000001',1,2::smallint,'17:00'::time,'18:00'::time,false);
select pg_temp.assert_true((select weekday=2 and not enabled and revision=2 from public.tutor_availability where id='80000000-0000-0000-0000-000000000001'), 'edit and disable persisted');
select pg_temp.expect_error($q$select public.save_tutor_availability('80000000-0000-0000-0000-000000000001',1,2::smallint,'17:00'::time,'18:00'::time,true)$q$,'40001','stale schedule edit rejected');
select pg_temp.expect_error($q$select public.delete_tutor_availability('80000000-0000-0000-0000-000000000001',1)$q$,'40001','stale removal rejected');
select public.delete_tutor_availability('80000000-0000-0000-0000-000000000001',2);
select public.delete_tutor_availability('80000000-0000-0000-0000-000000000001',2);
select pg_temp.assert_true((select count(*)=1 from public.tutor_availability), 'removal persisted and retry idempotent');
select pg_temp.expect_error($q$insert into public.tutor_availability(tutor_id,weekday,starts_at,ends_at) values(auth.uid(),1,'19:00','20:00')$q$,'42501','direct schedule write bypass revoked');
-- Fill Monday's remaining capacity and verify the bound at the trusted boundary.
select public.save_tutor_availability('80000000-0000-0000-0000-000000000002',null,1::smallint,'18:00'::time,'19:00'::time,true);
select public.save_tutor_availability('80000000-0000-0000-0000-000000000003',null,1::smallint,'19:00'::time,'20:00'::time,true);
select public.save_tutor_availability('80000000-0000-0000-0000-000000000004',null,1::smallint,'20:00'::time,'21:00'::time,true);
select pg_temp.expect_error($q$select public.save_tutor_availability('80000000-0000-0000-0000-000000000005',null,1::smallint,'21:00'::time,'22:00'::time,true)$q$,'23514','daily slot count enforced');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000008","session_id":"00000000-0000-0000-0000-000000000008"}',true);
select pg_temp.assert_true((select count(*)=0 from public.tutor_availability), 'another tutor cannot read private availability');
select pg_temp.assert_true((select count(*)=0 from public.tutor_subject_qualifications), 'another tutor cannot read qualifications');
select pg_temp.expect_error($q$select public.save_tutor_availability('80000000-0000-0000-0000-000000000002',2,1::smallint,'10:00'::time,'11:00'::time,true)$q$,'40001','another tutor cannot edit owned interval');
select public.delete_tutor_availability('80000000-0000-0000-0000-000000000002',1);
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","session_id":"00000000-0000-0000-0000-000000000001"}',true);
select pg_temp.assert_true((select count(*)=0 from public.tutor_profiles), 'learner cannot read tutor profiles');
select pg_temp.expect_error($q$select public.save_tutor_bio('learner',1)$q$,'42501','learner cannot edit tutor bio');
select pg_temp.expect_error($q$select public.save_tutor_availability(gen_random_uuid(),null,1::smallint,'10:00'::time,'11:00'::time,true)$q$,'42501','learner cannot create availability');
reset role;
delete from auth.sessions where user_id='00000000-0000-0000-0000-000000000003';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000003","session_id":"00000000-0000-0000-0000-000000000003"}',true);
select pg_temp.assert_true((select count(*)=0 from public.tutor_availability), 'revoked session loses schedule read access');
select pg_temp.expect_error($q$select public.save_tutor_bio('revoked',2)$q$,'42501','revoked session loses bio writes');
select pg_temp.expect_error($q$select public.save_tutor_availability(gen_random_uuid(),null,1::smallint,'10:00'::time,'11:00'::time,true)$q$,'42501','revoked session loses availability writes');
select pg_temp.expect_error($q$select public.delete_tutor_availability('80000000-0000-0000-0000-000000000002',1)$q$,'42501','revoked session loses delete access');
reset role;
set local role anon;
select pg_temp.expect_error($q$select * from public.tutor_availability$q$,'42501','anonymous schedule read denied');
select pg_temp.expect_error($q$select public.save_tutor_bio('anon',1)$q$,'42501','anonymous bio RPC denied');
select pg_temp.expect_error($q$select public.save_tutor_availability(gen_random_uuid(),null,1::smallint,'10:00'::time,'11:00'::time,true)$q$,'42501','anonymous schedule RPC denied');
reset role;
